create table xxventuri.eba_sales_deal_status_codes (
    id                     number,
    row_version_number     number,
    display_order          number,
    code_type              varchar2(30 byte),
    status_code            varchar2(255 byte) not null enable,
    corresponding_prob_pct number(3, 0) not null enable,
    code_description       varchar2(4000 byte),
    flex_01                varchar2(4000 byte),
    flex_02                varchar2(4000 byte),
    flex_03                varchar2(4000 byte),
    flex_04                varchar2(4000 byte),
    created_by             varchar2(255 byte),
    created                timestamp(6) with local time zone,
    updated_by             varchar2(255 byte),
    updated                timestamp(6) with local time zone,
    status                 varchar2(10 byte)
);

alter table xxventuri.eba_sales_deal_status_codes add primary key ( id )
    using index enable;


